class CircularQueue {
  constructor(capacity) {
    this.capacity = capacity;
    this.q = new Array(capacity);
    this.head = 0;
    this.count = 0;
  }
  enqueue(x) {
    if (this.count === this.capacity) return false;
    this.q[(this.head + this.count) % this.capacity] = x;
    this.count++;
    return true;
  }
  dequeue() {
    if (this.count === 0) return undefined;
    const x = this.q[this.head];
    this.head = (this.head + 1) % this.capacity;
    this.count--;
    return x;
  }
}

const cq = new CircularQueue(3);
cq.enqueue(1);
cq.enqueue(2);
cq.enqueue(3);
console.log(cq.dequeue(), cq.enqueue(4), cq.dequeue());

